/// Returns : 16-bit boot loader serial # msb.lsb == maj.min in bcd ///

UInt16 iap_rd_boot_code_ver (void)
{
  UInt32 arg_i [5] , arg_o [5] ;

  arg_i [0] = CMD_RD_BOOT_CODE ;

  iap_execute (arg_i , arg_o) ;

  return (UInt16) arg_o [1] ;
}

